import { useCallback } from 'react';
import { useStore } from '~/app/store/store';
import { NativeAuthnResult } from '~/entities/biometric/model/types';
import { UserResponse } from '~/entities/pin/api/dtos/schemas';
import { useVerifyPinMutation } from '~/entities/pin/api/use-verify-pin-mutation';
import { WebViewBridgeResponse } from '~/shared/@types/webview-bridge';
import { StepBeforeRegister } from '~/shared/api/dtos/enums';
import { NativeFunction } from '~/shared/constants/native-function';
import i18n from '~/shared/i18n/i18n';
import { useNavigate } from '~/shared/lib/hooks';
import { useAlertDialog } from '~/shared/lib/hooks/use-alert-dialog';
import { notiBar } from '~/shared/lib/toast';
import { PATHS } from '~/shared/routes/paths';
import { closeDialog } from '~/shared/ui/dialogs';

type NativeBiometricResponse = {
  data: NativeAuthnResult;
} & WebViewBridgeResponse;

type BiometricRegistrationParams = {
  webAuthnOptions: PublicKeyCredentialRequestOptions;
  username: string;
  userRes: UserResponse;
  step: string;
};

export const useAuthnNativeRegistration = () => {
  const { mutateAsync: login } = useVerifyPinMutation({ throwOnError: false });
  const { navigate } = useNavigate();
  const { openAlertDialog } = useAlertDialog();

  // 생체인증 등록 (네이티브 통신만 담당)
  const register = useCallback(
    async ({ webAuthnOptions, username, userRes, step }: BiometricRegistrationParams): Promise<NativeAuthnResult> => {
      return new Promise<NativeAuthnResult>((resolve, reject) => {
        // 앱이 아닌 경우 실행하지 않음
        if (!window.ReactNativeWebView) {
          //reject(new Error('네이티브 환경이 아닙니다.'));
          openAlertDialog({
            title: '생체인증 등록 오류',
            message: '네이티브 환경이 아닙니다.',
            onConfirmClick: () => {
              closeDialog(async () => {
                if (step === StepBeforeRegister.회원가입) {
                  //로그인 setting
                  useStore.getState().authSlice.setJwt(null);
                  await login(userRes);
                  useStore.getState().superAppSlice.clearSuperAppData();
                  notiBar(i18n.t('membershipComplete'));

                  //사업자 등록을 묻는 alert
                  openAlertDialog({
                    message: i18n.t('validation:registerBusinessInformation'),
                    buttonLabel: [i18n.t('cancel'), i18n.t('confirm')],
                    onConfirmClick: () => {
                      //확인 클릭 시 사업자 등록 화면으로 이동
                      closeDialog(() => {
                        navigate(PATHS.myWallet.business, { state: { step: StepBeforeRegister.회원가입 } });
                      });
                    },
                    onCancelClick: () => {
                      closeDialog(() => {
                        //취소 클릭 시 홈화면으로 이동
                        navigate(PATHS.home, { replace: true });
                      });
                    },
                  });
                }
              });
            },
          });

          //회원가입 중 네이티브 환경이 아닐경우 reject 후 사업자 등록여부 묻기
          //사업자 등록하지 않을경우 => 홈화면 이동
          return;
        }

        // 네이티브에 WebAuthn options와 username 전달
        window.webViewBridge.send(NativeFunction.BiometricRegister, {
          webAuthnOptions,
          username,
          success: (response: NativeBiometricResponse) => {
            resolve(response.data);
          },
          error: (nativeError: NativeBiometricResponse) => {
            console.error('네이티브 생체인증 등록 에러:', nativeError);
            reject(new Error(JSON.stringify(nativeError.data)));
          },
        });
      });
    },
    [],
  );

  return {
    register,
  };
};
